old:
.barcode-dual-outer-frame {
    display: none;
    position: relative;
    box-sizing: border-box;
    margin: 0 auto;
    padding: 0 48px 36px 0;
    pointer-events: auto;
}
.dual-barcode-layout.barcode-dual-unified-120x50 .barcode-dual-outer-frame {
    display: block;
}
.barcode-dual-outer-frame {
    border: 1px solid #1e293b;
    background: #fff;
}

new:
.barcode-dual-outer-frame {
    display: none;
    position: relative;
    box-sizing: content-box;
    margin: 0 auto;
    padding: 0 48px 36px 0;
    pointer-events: auto;
    border: 1px solid #1e293b;
    background: #fff;
}
.dual-barcode-layout.barcode-dual-unified-120x50 .barcode-dual-outer-frame {
    display: block;
}
